import ctypes
from cffi import FFI

ffi = FFI()
ffi.cdef("""
    void *EVP_CIPHER_CTX_new(void);
    void EVP_CIPHER_CTX_free(void *ctx);
    const void *EVP_aes_128_gcm(void);
    const void *EVP_aes_192_gcm(void);
    const void *EVP_aes_256_gcm(void);
    int EVP_EncryptInit_ex(void *ctx, const void *cipher, void *impl, const unsigned char *key, const unsigned char *iv);
    int EVP_EncryptUpdate(void *ctx, unsigned char *out, int *outl, const unsigned char *in, int inl);
    int EVP_EncryptFinal_ex(void *ctx, unsigned char *out, int *outl);
    int EVP_CIPHER_CTX_ctrl(void *ctx, int type, int arg, void *ptr);
""")
lib = ffi.dlopen('/Library/Frameworks/Python.framework/Versions/3.11/lib/libcrypto.3.dylib')

class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        associated_data = problem["associated_data"]

        key_len = len(key)
        if key_len == 16:
            cipher = lib.EVP_aes_128_gcm()
        elif key_len == 24:
            cipher = lib.EVP_aes_192_gcm()
        elif key_len == 32:
            cipher = lib.EVP_aes_256_gcm()
        else:
            raise ValueError("Invalid key length")

        ctx = lib.EVP_CIPHER_CTX_new()

        lib.EVP_EncryptInit_ex(ctx, cipher, ffi.NULL, ffi.NULL, ffi.NULL)
        lib.EVP_EncryptInit_ex(ctx, ffi.NULL, ffi.NULL, key, nonce)

        outl = ffi.new("int *")
        if associated_data:
            lib.EVP_EncryptUpdate(ctx, ffi.NULL, outl, associated_data, len(associated_data))

        pt_len = len(plaintext)
        ct = ffi.new("unsigned char[]", pt_len + 16)

        lib.EVP_EncryptUpdate(ctx, ct, outl, plaintext, pt_len)

        lib.EVP_EncryptFinal_ex(ctx, ct + outl[0], outl)

        tag = ffi.new("unsigned char[16]")
        lib.EVP_CIPHER_CTX_ctrl(ctx, 16, 16, tag)

        lib.EVP_CIPHER_CTX_free(ctx)

        return {
            "ciphertext": ffi.buffer(ct, pt_len)[:],
            "tag": ffi.buffer(tag, 16)[:]
        }
